#!/usr/bin/env node
/*
 * Create a short-lived, loopback-only CA and server certificate for the
 * local TON Connect relay. Nothing generated by this file belongs in git.
 * NSS installation is opt-in because it changes the browser trust store.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const args = new Set(process.argv.slice(2));
const certDir = process.env.PRIVA_TONCONNECT_CERT_DIR ||
  path.join(os.homedir(), '.local', 'state', 'priva', 'tonconnect-dev');
const nssDb = process.env.PRIVA_NSS_DB || path.join(os.homedir(), '.pki', 'nssdb');
const nickname = 'Priva local TON Connect CA';
const caKey = path.join(certDir, 'ca.key');
const caCert = path.join(certDir, 'ca.crt');
const serverKey = path.join(certDir, 'server.key');
const serverCsr = path.join(certDir, 'server.csr');
const serverCert = path.join(certDir, 'server.crt');
const serial = path.join(certDir, 'ca.srl');
const extConfig = path.join(certDir, 'server-ext.cnf');

function run(command, commandArgs, options = {}) {
  const result = spawnSync(command, commandArgs, { encoding: 'utf8', stdio: options.stdio || 'inherit' });
  if (result.error) throw result.error;
  if (result.status !== 0 && !options.allowFailure) {
    throw new Error(`${command} exited with status ${result.status}`);
  }
  return result;
}

function ensureDir() {
  fs.mkdirSync(certDir, { recursive: true, mode: 0o700 });
  try { fs.chmodSync(certDir, 0o700); } catch {}
}

function createCertificates() {
  if (fs.existsSync(caKey) && fs.existsSync(caCert) && fs.existsSync(serverKey) && fs.existsSync(serverCert)) {
    return;
  }

  fs.writeFileSync(extConfig, [
    '[v3_server]',
    'basicConstraints=critical,CA:FALSE',
    'keyUsage=critical,digitalSignature,keyEncipherment',
    'extendedKeyUsage=serverAuth',
    'subjectAltName=DNS:localhost,IP:127.0.0.1,IP:::1',
    '',
  ].join('\n'), { mode: 0o600 });

  run('openssl', [
    'req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-sha256', '-days', '30',
    '-keyout', caKey, '-out', caCert,
    '-subj', '/CN=Priva local TON Connect development CA',
  ]);
  run('openssl', [
    'req', '-new', '-newkey', 'rsa:2048', '-nodes',
    '-keyout', serverKey, '-out', serverCsr,
    '-subj', '/CN=localhost',
  ]);
  run('openssl', [
    'x509', '-req', '-sha256', '-days', '30',
    '-in', serverCsr, '-CA', caCert, '-CAkey', caKey, '-CAcreateserial',
    '-out', serverCert, '-extfile', extConfig, '-extensions', 'v3_server',
  ]);

  for (const file of [caKey, caCert, serverKey, serverCert]) {
    try { fs.chmodSync(file, file.endsWith('.key') ? 0o600 : 0o644); } catch {}
  }
  for (const file of [serverCsr, serial, extConfig]) {
    try { fs.rmSync(file, { force: true }); } catch {}
  }
}

function installNss() {
  if (!fs.existsSync(path.join(nssDb, 'cert9.db'))) {
    throw new Error(`NSS database not found at ${nssDb}; set PRIVA_NSS_DB to the Brave profile NSS database.`);
  }
  run('certutil', ['-D', '-d', `sql:${nssDb}`, '-n', nickname], { allowFailure: true });
  run('certutil', ['-A', '-d', `sql:${nssDb}`, '-n', nickname, '-t', 'C,,', '-i', caCert]);
  console.log(`Installed ${nickname} in ${nssDb}`);
}

function removeNss() {
  if (!fs.existsSync(path.join(nssDb, 'cert9.db'))) {
    throw new Error(`NSS database not found at ${nssDb}; set PRIVA_NSS_DB to the Brave profile NSS database.`);
  }
  run('certutil', ['-D', '-d', `sql:${nssDb}`, '-n', nickname], { allowFailure: true });
  console.log(`Removed ${nickname} from ${nssDb}`);
}

if (args.has('--remove-nss')) {
  removeNss();
} else {
  ensureDir();
  createCertificates();
  if (args.has('--install-nss')) installNss();
  console.log(`certDir=${certDir}`);
  console.log(`serverCertificate=${serverCert}`);
  console.log(`serverKey=${serverKey}`);
  if (!args.has('--install-nss')) {
    console.log(`Run with --install-nss to trust the CA in ${nssDb}.`);
  }
}
